def write_json(path: Path, payload: dict) -> None:
    path.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)

    reading_path = OUT_DIR / "platform-reading-tags.json"
    content_path = OUT_DIR / "platform-content-tags.json"

    write_json(
        reading_path,
        {
            "schema_version": SCHEMA_VERSION,
            "platform": PLATFORM,
            "tag_type": "reading",
            "exported": EXPORTED,
            "code": 0,
            "message": "success",
            "data": READING_TAGS,
        },
    )

    write_json(
        content_path,
        {
            "schema_version": SCHEMA_VERSION,
            "platform": PLATFORM,
            "tag_type": "content",
            "exported": EXPORTED,
            "code": 0,
            "message": "success",
            "data": CONTENT_TAGS,
        },
    )

    for path in (reading_path, content_path):
        data = json.loads(path.read_text(encoding="utf-8"))
        size = path.stat().st_size
        print(f"{path.name}: {len(data['data'])} items, {size} bytes")


if __name__ == "__main__":
    main()
